from pkg_info import installed_version


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return a dict mapping each given distribution name to its installed version string or None if missing."""
    return {name: installed_version(name) for name in names}

import http_client


def make_proxied_client(proxy_url: str, base_url: str) -> http_client.httpx.Client:
    """Return an httpx client for base_url with all requests routed through proxy_url.

    Uses a 5-second timeout and sets User-Agent: inventory-sync/1.0 header on every request.
    """
    headers = {"User-Agent": "inventory-sync/1.0"}
    return http_client.make_client(base_url, headers=headers, timeout=5, proxy_url=proxy_url)

